export const CATEGORY_BY_ID: Record<string, CategoryOption> = Object.fromEntries(
  CATEGORIES.map((c) => [c.id, c]),
);

export function categoryLabel(id: string, lang: Lang): string {
  const c = CATEGORY_BY_ID[id];
  if (!c) return id;
  return lang === 'fr' ? c.nameFr ?? c.name : c.name;
}

export function categoryColor(id: string): string {
  return CATEGORY_BY_ID[id]?.color ?? '#1F7A8C';
}
